// Se queda solo con los mensajes del formulario del portafolio (EmailJS).
// EmailJS los manda desde mi propia dirección: el correo del cliente viene en Reply-To,
// el nombre en el asunto y el mensaje en el cuerpo (con o sin etiquetas "Nombre:", "Email:", "Mensaje:").
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const texto = String(j.textPlain || String(j.textHtml || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ') || '');
  const html = String(j.textHtml || '');
  if (!/emailjs\.com/i.test(texto + html)) continue;
  const campo = (...nombres) => {
    for (const n of nombres) {
      const m = texto.match(new RegExp('^\\s*' + n + '\\s*[:：]\\s*(.+)$', 'im'));
      if (m) return m[1].trim();
    }
    return '';
  };
  const meta = j.metadata || {};
  const correo = (String(meta['reply-to'] || '').match(/[\w.+-]+@[\w-]+\.[\w.-]+/)?.[0]
    || campo('email', 'correo', 'e-mail').match(/[\w.+-]+@[\w-]+\.[\w.-]+/)?.[0] || '').toLowerCase();
  let mensaje;
  const pos = texto.search(/^\s*(mensaje|message)\s*[:：]/im);
  if (pos >= 0) mensaje = texto.slice(pos).replace(/^\s*(mensaje|message)\s*[:：]\s*/i, '');
  else mensaje = texto.replace(/👤/g, '');
  mensaje = mensaje.replace(/Email sent via EmailJS\.com.*$/is, '').replace(/\r/g, '')
    .split(/\n{2,}/).map(p => p.replace(/\s*\n\s*/g, ' ').trim()).filter(Boolean).join('\n\n');
  const asunto = String(j.subject || '').trim();
  const nombre = campo('nombre', 'name') || asunto.replace(/^(nuevo mensaje( desde el portafolio)?|contact us|mensaje)\s*[:\-–]\s*/i, '').trim() || correo.split('@')[0];
  out.push({ json: { mensaje_id: String(meta['message-id'] || `${j.date}|${correo}`).trim(), nombre: nombre.slice(0, 80), correo, mensaje: mensaje.slice(0, 3000), asunto, fecha: j.date ? new Date(j.date).toISOString() : new Date().toISOString() } });
}
return out;

// Si el vigilante o el monitor relanzan una ejecución, el mismo correo vuelve a entrar.
// Se descarta si ya se guardó y respondió (o si era malo); si se guardó pero falló la respuesta, sigue.
const leads = $('Leer formulario').all();
const salida = [];
$input.all().forEach((item, i) => {
  const previo = (item.json.data || [])[0];
  if (previo && (previo.respondido_auto || previo.calidad === 'malo')) return;
  salida.push({ json: { ...leads[i].json, previoId: previo?.id ?? null }, pairedItem: i });
});
return salida;

