// Junta el lead con lo que dijo la IA. Si la IA falla o responde mal, puntúa con reglas simples.
const lead = $('¿Ya procesado?').item.json;
let ia = null;
try { ia = JSON.parse(String($json.text || '').match(/\{[\s\S]*\}/)[0]); } catch {}
const m = lead.mensaje.toLowerCase();
const reglas = () => {
  let p = 4;
  if (/\$|usd|presupuesto|budget|d[oó]lares|euros/.test(m)) p += 2;
  if (/plazo|semana|d[ií]as|deadline|urgente/.test(m)) p += 1;
  if (m.length > 200) p += 1;
  if (/seo|backlink|guest post|crypto|bitcoin|casino|loan/.test(m)) p = 1;
  const tipo = /minecraft|servidor|tebex|plugin|kubejs/.test(m) ? 'minecraft' : /n8n|automatiz|bot|telegram/.test(m) ? 'automatizacion' : /api|backend/.test(m) ? 'api' : /web|tienda|p[aá]gina|shop/.test(m) ? 'web' : 'otro';
  return { tipo, presupuesto: '', plazo: '', tema: '', resumen: lead.mensaje.slice(0, 80), puntuacion: p, idioma: /\b(the|hello|hi|please|website)\b/.test(m) ? 'en' : 'es', spam: p <= 1 };
};
const d = ia && typeof ia.puntuacion !== 'undefined' ? ia : reglas();
const puntuacion = Math.max(1, Math.min(10, Number(d.puntuacion) || 1));
const calidad = d.spam ? 'malo' : puntuacion >= 7 ? 'bueno' : puntuacion >= 4 ? 'medio' : 'malo';
const correoValido = /^[\w.+-]+@[\w-]+\.[\w.-]+$/.test(lead.correo);
return { json: { ...lead, tipo: d.tipo || 'otro', presupuesto: d.presupuesto || '', plazo: d.plazo || '', tema: String(d.tema || '').trim(),
  resumen: String(d.resumen || '').slice(0, 160), puntuacion, calidad, idioma: d.idioma === 'en' ? 'en' : 'es', spam: !!d.spam,
  responder: correoValido && !d.spam && calidad !== 'malo', origen: ia ? 'ia' : 'reglas' } };

