={{ (() => {
  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const l = $('Puntuar').item.json;
  const icono = { bueno: '🟢', medio: '🟡', malo: '🔴' }[l.calidad];
  let respondido = 'No se respondió automáticamente';
  try { if ($('Respuesta automática').isExecuted) respondido = '✉️ Ya le llegó la respuesta automática'; } catch {}
  return `${icono} <b>Lead ${l.calidad}</b> · ${l.puntuacion}/10 · ${esc(l.tipo)}\n<b>${esc(l.nombre)}</b> &lt;${esc(l.correo)}&gt;\n${esc(l.resumen)}` +
    (l.presupuesto ? `\n💰 ${esc(l.presupuesto)}` : '') + (l.plazo ? `\n⏱ ${esc(l.plazo)}` : '') +
    `\n\n<i>${esc(l.mensaje.slice(0, 500))}</i>\n\n${respondido}`;
})() }}
